import {createIcons,icons} from 'lucide';
import {CATALOG,clone,defaultModel,makeNode,simulate,histogram,stats,symbolic,toSysML} from './engine.js';
import * as repo from './repository.js';
const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<i data-lucide="${n}"></i>`,fmt=n=>Number.isFinite(n)?Math.abs(n)>9999?n.toExponential(2):n.toFixed(3):'—';
const state={tabs:[],active:0,selected:'logistic',selection:new Set(['logistic']),search:'',favorites:false,closed:new Set(['Math','Calculus','Combinatorics','Logic','Dynamics']),history:[],branches:[],panel:'history',panelClosed:false,filter:'all',zoom:1,pan:{x:0,y:0},tool:'select',pending:null,split:false,compare:1,source:false,sim:null,busy:false,clipboard:null};
const active=()=>state.tabs[state.active],model=()=>active().model;
let toastTimer,runTimer;
function toast(message){const e=$('#toast');e.textContent=message;e.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('visible'),3400);}
function refreshIcons(){createIcons({icons,attrs:{'aria-hidden':'true'}});}
function persist(){try{localStorage.setItem('chaos-lab-tabs-v1',JSON.stringify({tabs:state.tabs.map(t=>({...t,undo:[],redo:[]})),active:state.active}));}catch{toast('Device storage is full. Export your repository to keep a backup.');}}
function edit(fn,rerender=true){const t=active();t.undo.push(clone(t.model));if(t.undo.length>60)t.undo.shift();t.redo=[];fn(t.model);t.dirty=true;persist();runSimulation();if(rerender)render();}
function effectiveR(n){const e=model().edges.find(e=>e.to===n.id&&e.port==='r');return e?model().nodes.find(n=>n.id===e.from)?.params.value:n.params.r;}
function runSimulation(){const start=performance.now();state.sim=simulate(model());state.elapsed=performance.now()-start;}
function button(action,label,ic,cls='icon-btn',extra=''){return `<button class="${cls}" data-action="${action}" title="${esc(label)}" aria-label="${esc(label)}" ${extra}>${ic?icon(ic):''}${cls==='icon-btn'?'':esc(label)}</button>`;}
function render(){
 const t=active(),m=t.model;
 $('#app').innerHTML=`<header class="topbar"><div class="brand"><img src="icon.svg" alt="Chaos Lab"><span>chaos<span>lab</span><sup style="font-size:8px;letter-spacing:0;margin-left:5px;color:#b1b9b0;font-weight:400">BETA</sup></span></div><nav class="topnav" aria-label="Main navigation"><button class="active" data-action="workspace">Workspace</button><button data-action="experiments">Experiments</button><button data-action="library">Block library</button></nav><div class="top-spacer"></div><span class="project-chip">PERSONAL WORKSPACE</span><button class="top-help" data-action="help">${icon('circle-help')}<span>Quick guide</span></button><div class="avatar" title="Your local workspace">Y</div></header>
 <div class="workspacebar"><div><div class="crumb">${icon('folder-open')}<button data-action="projects" class="muted">My workspace</button><span class="slash">/</span><button data-action="rename" class="model-title">${esc(m.name)}</button>${button('rename','Rename model','chevron-down')}</div><div class="saved-status"><span class="dot" style="${t.dirty?'background:#c2a471':''}"></span>${t.dirty?'Uncommitted changes':'All changes committed'}<span style="margin-left:5px;color:#bcc4bc">·</span><span class="mono" style="font-size:9px;margin-left:4px">${esc(m.branch)}</span></div></div><div class="actions"><div class="undo-actions">${button('undo','Undo · Ctrl Z','undo-2','icon-btn',t.undo.length?'':'disabled')}${button('redo','Redo · Ctrl Shift Z','redo-2','icon-btn',t.redo.length?'':'disabled')}</div><div class="divider"></div>${button('source','SysML','code-xml','btn source-action')}${button('save',state.busy?'Committing…':'Commit','git-commit-horizontal','btn outline',state.busy?'disabled':'')}${button('run','Run simulation','play','btn green')}</div></div>
 <div class="main-grid"><aside class="rail" aria-label="Workspace panels">${button('library','Block library','blocks','active')}${button('projects','Models','folder-open')}${button('git','Git history','git-branch')}${button('analytics','Simulation results','chart-no-axes-combined')}${button('source','SysML source','file-code-2')}<div class="bottom">${button('settings','Simulation settings','settings-2')}${button('help','Keyboard shortcuts','circle-help')}</div></aside>
 <aside class="library"><div class="library-head"><div class="section-title">Block library<span class="small-badge">${CATALOG.length}</span></div><p>A little structure. Infinite possibilities.</p><label class="searchbox">${icon('search')}<input id="block-search" placeholder="Search blocks…" aria-label="Search blocks" value="${esc(state.search)}"><kbd>/</kbd></label></div><div class="library-tabs"><button data-action="allblocks" class="${!state.favorites?'active':''}">All blocks</button><button data-action="favorites" class="${state.favorites?'active':''}">Favorites <span style="font-size:9px;margin-left:3px">☆</span></button></div><div class="categories" id="categories">${libraryHTML()}</div><div class="library-footer">${icon('mouse-pointer-2')}Drag a block onto the canvas</div></aside>
 <main class="center"><div class="tabs-bar"><div class="model-tabs">${state.tabs.map((tab,i)=>`<div class="model-tab ${state.active===i?'active':''}" data-tab="${i}" role="tab" aria-selected="${state.active===i}" tabindex="0">${icon('workflow')}<span>${esc(tab.model.name=== 'Logistic exploration'?'logistic_map':tab.model.name.replace(/ /g,'_').toLowerCase())}</span><span class="tab-branch">${esc(tab.model.branch)}</span>${tab.dirty?'<span style="color:#b39b78">•</span>':''}${state.tabs.length>1?`<button class="close-tab" data-close-tab="${i}" title="Close model tab">×</button>`:''}</div>`).join('')}</div>${button('new','New model','plus')}${button('split',state.split?'Merge view':'Split view','columns-2')}</div>
 <section class="canvas-wrap ${state.split?'split-mode':''}" id="canvas" aria-label="Visual model canvas"><div class="canvas-title"><strong>${state.split?'Compare designs':'A small equation. A world of chaos.'}</strong><p>${state.split?'Select a block on the right to copy it into your active model.':'Connect, experiment, and see what emerges.'}</p></div><div class="canvas-live"><span class="dot"></span>Seeded simulation<span style="color:#b8c4b7">|</span><span class="mono">${m.samples.toLocaleString()} samples</span></div><div class="canvas-plane" id="plane" ${state.zoom!==1||state.pan.x||state.pan.y?`style="transform:translate(${state.pan.x}px,${state.pan.y}px) scale(${canvasScale()*state.zoom})"`:''}>${graphHTML(m)}</div><div class="canvas-toolbar">${button('select','Select · V','mouse-pointer-2',`icon-btn ${state.tool==='select'?'active':''}`)}${button('pan','Pan · H','hand',`icon-btn ${state.tool==='pan'?'active':''}`)}${button('tap','Add distribution tap · T','chart-no-axes-column-increasing',`icon-btn ${state.tool==='tap'?'active':''}`)}<div class="divider"></div>${button('zoomout','Zoom out','minus')}<span class="zoom-label mono">${Math.round(state.zoom*100)}%</span>${button('zoomin','Zoom in','plus')}${button('fit','Fit canvas','scan')}</div><div class="minimap" aria-hidden="true"><div class="view"></div>${m.nodes.map(n=>`<span class="mini-node" style="left:${n.x/9+6}px;top:${n.y/10+6}px;${n.type==='tap'?'width:25px;background:#c4d9c3':''}"></span>`).join('')}</div><div class="canvas-hint">${state.pending?'Select an input port to connect':state.tool==='tap'?'Click an input or output port to inspect':'Scroll to pan · Ctrl + scroll to zoom'}</div>${state.split?splitHTML():''}${state.source?sourceHTML():''}</section>
 <section class="git-panel ${state.gitExpanded?'expanded':''} ${state.panelClosed?'collapsed':''}"><div class="panel-header"><button class="panel-tab ${state.panel==='history'?'active':''}" data-action="git">${icon('git-branch')}Version history<span class="count">${state.history.length}</span></button><button class="panel-tab ${state.panel==='simulation'?'active':''}" data-action="analytics">${icon('activity')}Simulation</button><div class="panel-spacer"></div><span class="repo-local">${icon('hard-drive')}Local Git repository</span>${button('export','Export repository','download')}${button('expandgit',state.gitExpanded?'Restore panel':'Expand Git window','maximize-2')}${button('togglepanel',state.panelClosed?'Expand panel':'Collapse panel',state.panelClosed?'chevron-up':'chevron-down')}</div>${!state.panelClosed?`<div class="panel-content">${state.panel==='history'?historyHTML():simulationHTML()}</div>`:''}</section></main>
 <aside class="inspector" id="inspector">${inspectorHTML()}</aside></div><footer class="statusbar"><span>${icon('git-branch')}<span class="mono">${esc(m.branch)}</span></span><span><span class="dot"></span>${state.sim.errors.length?state.sim.errors.length+' model issue(s)':'Model ready'}</span><span class="optional">${icon('box')}${m.nodes.filter(n=>n.type!=='tap').length} blocks</span><span class="optional">${icon('cable')}${m.edges.length} connections</span><span class="spacer"></span><span class="optional">${icon('braces')}SysML 2.0 draft</span><span class="mono">${m.samples.toLocaleString()} samples</span><span class="mono">${Math.max(1,state.elapsed).toFixed(0)} ms</span><span class="optional">${icon('shield-check')}Saved on this device</span></footer>`;
 refreshIcons();bindSearch();
}
function canvasScale(){if(innerWidth<=700)return .58;if(innerWidth<=1000)return .8;if(innerWidth<=1250)return .76;if(innerHeight<=830)return .76;return .88;}
function libraryHTML(){const groups=[...new Set(CATALOG.map(c=>c.category))],fav=['uniform','normal','logistic','custom','add','multiply','differentiate','integrate','tap','delay'];let found=0;const html=groups.map(group=>{const items=CATALOG.filter(c=>c.category===group&&(!state.favorites||fav.includes(c.op))&&`${c.name} ${c.category}`.toLowerCase().includes(state.search.toLowerCase()));if(!items.length)return '';found+=items.length;const closed=!state.search&&state.closed.has(group);return `<div class="category"><button class="category-title" data-category="${group}">${icon(closed?'chevron-right':'chevron-down')}${group}<span>${items.length}</span></button>${!closed?items.map(c=>`<div class="block-item ${c.type}" draggable="true" data-block="${c.op}" tabindex="0" role="button" title="Drag to canvas or double-click to add"><span class="block-symbol">${c.symbol}</span><span>${esc(c.name)}${['uniform','normal','logistic','custom'].includes(c.op)?`<small>${{uniform:'Evenly distributed values',normal:'The familiar bell curve',logistic:'r · x · (1 − x)',custom:'Your own expression'}[c.op]}</small>`:''}</span><span class="drag-dots">⠿</span></div>`).join(''):''}</div>`;}).join('');return found?html:'<div class="empty-library">No matching blocks.<br>Try “random” or “integrate”.</div>';}
function bindSearch(){$('#block-search').addEventListener('input',e=>{state.search=e.target.value;$('#categories').innerHTML=libraryHTML();refreshIcons();});}
function nodeWidth(n){return n.type==='tap'?(n.id==='outputTap'||n.source?.id==='logistic'?280:227):n.type==='function'?217:n.type==='delay'?165:177;}
function outPoint(n){return {x:n.x+nodeWidth(n),y:n.y+70};}
function inPoint(n,port='x'){return port==='r'?{x:n.x+nodeWidth(n)/2,y:n.y}:{x:n.x,y:n.y+(port==='b'?93:70)};}
function curve(a,b){const dx=Math.max(35,Math.abs(b.x-a.x)*.45);return `M ${a.x} ${a.y} C ${a.x+dx} ${a.y}, ${b.x-dx} ${b.y}, ${b.x} ${b.y}`;}
function graphHTML(m,compare=false){let wires=m.edges.map(e=>{const a=m.nodes.find(n=>n.id===e.from),b=m.nodes.find(n=>n.id===e.to);if(!a||!b)return '';const p=outPoint(a),q=inPoint(b,e.port);if(e.port==='feedback')return `<path class="wire feedback" d="M ${p.x} ${p.y} L ${p.x+20} ${p.y} Q ${p.x+30} ${p.y} ${p.x+30} ${p.y+20} L ${p.x+30} ${p.y+80} Q ${p.x+30} ${p.y+90} ${p.x+20} ${p.y+90} L ${q.x-20} ${p.y+90} Q ${q.x-30} ${p.y+90} ${q.x-30} ${p.y+80} L ${q.x-30} ${q.y+20} Q ${q.x-30} ${q.y} ${q.x-20} ${q.y} L ${q.x} ${q.y}"/>`;
 if(e.port==='r')return `<path class="wire" d="M ${p.x} ${p.y} C ${p.x+35} ${p.y} ${q.x} ${q.y-20} ${q.x} ${q.y}"/>`;
 return `<path class="wire" d="${curve(p,q)}"/>`;}).join('');
 for(const n of m.nodes.filter(n=>n.type==='tap'&&n.source)){const s=m.nodes.find(s=>s.id===n.source.id);if(!s)continue;const p=n.source.port==='in'?inPoint(s):outPoint(s),q={x:n.x+nodeWidth(n)/2,y:n.y};wires+=`<path class="wire tap-wire" d="M ${p.x} ${p.y} L ${p.x+15} ${p.y} Q ${p.x+25} ${p.y} ${p.x+25} ${p.y+12} L ${p.x+25} ${q.y-28} Q ${p.x+25} ${q.y-17} ${p.x+12} ${q.y-17} L ${q.x+12} ${q.y-17} Q ${q.x} ${q.y-17} ${q.x} ${q.y}"/><circle class="wire-dot" cx="${p.x}" cy="${p.y}" r="2.4"/>`;}
 return `<svg class="wires" aria-hidden="true">${wires}</svg>`+m.nodes.map(n=>nodeHTML(n,compare)).join('');}
function nodeHTML(n,compare=false){const selected=!compare&&state.selection.has(n.id);const m=compare?state.tabs[state.compare]?.model:model();let body='';if(n.type==='tap'){const v=compare?state.compareSim?.values[n.id]:state.sim.values[n.id],s=stats(v||[]);return `<article class="node tap-node ${nodeWidth(n)===280?'output':''} ${selected?'selected':''}" data-node="${n.id}" ${compare?'data-compare-node="true"':''} style="left:${n.x}px;top:${n.y}px"><span class="tap-tag">${n.source?.port==='in'?'INPUT':'OUTPUT'} TAP · ${esc(m.nodes.find(s=>s.id===n.source?.id)?.name||'Unattached')}</span><div class="node-header">${icon('chart-no-axes-column-increasing')}<span class="node-title">${esc(n.name)}</span><span style="font-size:8px;color:#9cae9e">${s.n.toLocaleString()} points</span></div><div class="node-body">${histogramSVG(v||[])}<div class="tap-stats"><span>μ<b>${fmt(s.mean)}</b></span><span>σ<b>${fmt(s.sd)}</b></span><span>bins<b>34</b></span></div></div><button class="port" data-port="tap" data-id="${n.id}" aria-label="Attach tap"></button></article>`;}
 if(n.type==='random'){body=`<div class="node-detail"><span>${n.op==='uniform'?'Range':n.op==='normal'?'Mean / σ':'Distribution'}</span><span class="mono">${n.op==='uniform'?`[${n.params.min}, ${n.params.max}]`:n.op==='normal'?`${n.params.mean} / ${n.params.sigma}`:n.op}</span></div><div class="node-detail"><span>Seed</span><span class="mono">${m.seed}</span></div>`;}else if(n.type==='parameter'){body=`<div class="node-detail"><span>r</span><span class="mono" style="font-size:13px">${n.params.value}</span></div>`;}else if(n.type==='delay'){body='<div class="formula" style="font-size:15px">z⁻¹</div><div class="node-detail"><span>One iteration back</span><span class="mono">xₙ</span></div>';}else{body=`<div class="formula">${n.op==='logistic'?'r · x · (1 − x)':n.op==='custom'?esc(n.params.expression):n.type==='calculus'?`${n.symbol} ${esc(n.params.expression)}`:n.type==='math'?`x ${n.symbol} b`:n.symbol+'(x)'}</div>`;}
 const hasInput=!['random','parameter'].includes(n.type),hasR=['logistic','custom','tent'].includes(n.op),binary=['add','subtract','multiply','divide','power','modulo','min','max','combination','permutation','greater','less','equal','and','or'].includes(n.op);
 return `<article class="node ${n.type} ${selected?'selected':''}" data-node="${n.id}" ${compare?'data-compare-node="true"':''} style="left:${n.x}px;top:${n.y}px"><div class="node-header"><span class="node-icon">${n.symbol}</span><span class="node-title">${esc(n.name)}</span><span class="node-menu">···</span></div><div class="node-body">${body}</div>${n.type!=='parameter'?`<div class="node-footer"><span>${{random:'RANDOM SOURCE',function:'NONLINEAR FUNCTION',delay:'DISCRETE DYNAMICS',calculus:'SYMBOLIC OPERATOR',math:'MATH OPERATOR',logic:'LOGIC OPERATOR',combinatorics:'COMBINATORICS'}[n.type]||n.type}</span><span>ℝ → ℝ</span></div>`:''}${hasInput?`<button class="port in" data-port="x" data-id="${n.id}" aria-label="${esc(n.name)} input x"></button><span class="port-label">x</span>`:''}${hasR?`<button class="port r" data-port="r" data-id="${n.id}" aria-label="${esc(n.name)} growth rate input"></button>`:''}${binary?`<button class="port b" data-port="b" data-id="${n.id}" aria-label="${esc(n.name)} input b"></button>`:''}<button class="port out ${state.pending?.id===n.id?'pending':''}" data-port="out" data-id="${n.id}" aria-label="${esc(n.name)} output"></button><span class="port-label right">${n.type==='delay'?'xₙ':'out'}</span></article>`;}
function histogramSVG(values){const h=histogram(values),max=Math.max(1,...h.counts);return `<svg class="histogram" viewBox="0 0 240 87" preserveAspectRatio="none" role="img" aria-label="Distribution histogram with ${h.n} samples"><line x1="0" x2="240" y1="19" y2="19" class="axis-line" stroke-dasharray="2 3"/><line x1="0" x2="240" y1="43" y2="43" class="axis-line" stroke-dasharray="2 3"/>${h.counts.map((v,i)=>`<rect x="${i*7.05+.6}" y="${68-v/max*60}" width="5.5" height="${v/max*60}" rx=".7" fill="${i%3===0?'#86ab80':'#a1bd94'}" opacity="${.65+v/max*.3}"/>`).join('')}<line x1="0" x2="240" y1="68" y2="68" class="axis-line"/><text class="chart-axis" x="0" y="82">${h.min.toFixed(2)}</text><text class="chart-axis" x="112" y="82">${((h.min+h.max)/2).toFixed(2)}</text><text class="chart-axis" x="240" text-anchor="end" y="82">${h.max.toFixed(2)}</text></svg>`;}
function historyHTML(){
 const logs=state.history.filter(c=>state.filter==='all'||c.branches.includes(state.filter)),lanes=['main',...new Set(logs.map(c=>c.branch).filter(b=>b!=='main'))],lane=c=>7+14*lanes.indexOf(c.branch),width=Math.max(38,lanes.length*14+7);
 const paths=logs.map((c,i)=>c.commit.parent.map(parent=>{const j=logs.findIndex(p=>p.oid===parent);if(j<0)return '';const x=lane(c),y=i*32+16,px=lane(logs[j]),py=j*32+16,mid=(y+py)/2;return `<path d="M ${x} ${y} C ${x} ${mid} ${px} ${mid} ${px} ${py}" fill="none" stroke="${c.branch==='main'?'#92b59b':'#b69acc'}" stroke-width="1.5"/>`;}).join('')).join('');
 return `<div class="git-controls">${icon('git-branch')}<select class="branch-select" id="branch-filter" aria-label="Filter Git branches"><option value="all">All branches</option>${state.branches.map(b=>`<option ${state.filter===b?'selected':''}>${esc(b)}</option>`).join('')}</select><button class="branch-button" data-action="newbranch">${icon('plus')}New branch</button><span class="right">Double-click a commit to open</span></div>${logs.map((c,i)=>{const exp=c.branch!=='main',selected=active().base===c.oid,labels=Object.entries(state.heads||{}).filter(([b,oid])=>oid===c.oid);return `<div class="commit-row ${selected?'selected':''}" data-commit="${c.oid}" tabindex="0" title="Double-click to open ${esc(c.commit.message.split('\n')[0])}"><svg class="tree" viewBox="0 ${i*32} ${width} 32" aria-hidden="true">${paths}<circle cx="${lane(c)}" cy="${i*32+16}" r="3.5" fill="${selected?'#76a486':'white'}" stroke="${exp?'#ad92c5':'#82aa8c'}" stroke-width="1.5"/></svg><span class="commit-title">${esc(c.commit.message.split('\n')[0])}</span>${labels.slice(0,2).map(([b])=>`<span class="branch-label ${b!=='main'?'purple':''}">${esc(b)}</span>`).join('')}<span class="commit-ref">${c.oid.slice(0,7)}</span><span class="commit-time">${relativeTime(c.commit.author.timestamp)}</span></div>`;}).join('')}`;
}
function relativeTime(ts){const mins=Math.max(0,Math.floor((Date.now()/1000-ts)/60));return mins<1?'just now':mins<60?mins+'m ago':Math.floor(mins/60)+'h ago';}
function inputField(key,label,value,type='number',extra=''){return `<div class="field"><label class="field-label" for="param-${key}">${label}</label><input class="field-input ${type==='text'?'':'mono'}" id="param-${key}" data-param="${key}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function inspectorHTML(){const n=model().nodes.find(n=>n.id===state.selected);if(!n)return `<div class="inspector-heading">Inspector</div><div class="empty">Select a block to explore its parameters.<br><br>Drag from the library to add your next idea.</div>`;const s=stats(state.sim.values[n.id]||[]),expr=['function','calculus'].includes(n.type),r=effectiveR(n);let params='';
 if(['logistic','custom','tent'].includes(n.op))params+=`<div class="field"><label class="field-label" for="growth-range">Growth rate <span class="unit">r</span></label><div class="range-line"><input id="growth-range" type="range" min="0" max="4" step="0.01" value="${r}" data-range="r" aria-label="Growth rate"><input class="number-input" aria-label="Growth rate value" data-param="r" type="number" step="0.01" value="${r}"></div><div class="range-scale"><span>0</span><span>2</span><span>4</span></div></div>`;
 if(expr)params+=`<div class="field"><label class="field-label" for="expression">Expression<span class="unit">ƒ(x)</span></label><div class="formula-input"><span>ƒ</span><input id="expression" class="field-input mono" data-param="expression" value="${esc(n.params.expression)}" spellcheck="false"></div><p class="field-help">${n.type==='calculus'?'Symbolic result':'∂ƒ / ∂x'} <code>${esc(symbolic(n.params.expression,n.op==='integrate'?'integrate':'differentiate'))}</code></p></div>`;
 if(n.type==='parameter')params+=inputField('value','Constant value',n.params.value,'number','step="0.01"');
 if(n.type==='random'){const keys=n.op==='uniform'?['min','max']:n.op==='normal'?['mean','sigma']:n.op==='bernoulli'?['p']:n.op==='beta'?['a','b']:['lambda'];for(const k of keys)params+=inputField(k,{min:'Minimum',max:'Maximum',mean:'Mean · μ',sigma:'Standard deviation · σ',lambda:'Rate · λ',p:'Probability · p',a:'Alpha · α',b:'Beta · β'}[k],n.params[k],'number','step="0.1"');}
 if(n.type==='math'||n.type==='logic'||n.type==='combinatorics')params+=inputField('b','Second operand · b',n.params.b,'number','step="0.1"');
 if(n.op==='clamp')params+=inputField('min','Minimum',n.params.min)+inputField('max','Maximum',n.params.max);
 if(n.op==='switch')params+=inputField('p','Threshold',n.params.p)+inputField('a','If true',n.params.a)+inputField('b','If false',n.params.b);
 if(n.type==='delay')params='<p class="field-help">Stores the previous iteration. Route its output back to a function to create a feedback loop.</p>';
 if(n.type==='tap')params=`<div class="field"><label class="field-label">Observe block</label><select class="field-input" id="tap-source"><option value="">Choose a block…</option>${model().nodes.filter(n=>n.type!=='tap').map(s=>`<option value="${s.id}" ${n.source?.id===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label class="field-label">Observe port</label><select class="field-input" id="tap-port"><option value="out" ${n.source?.port==='out'?'selected':''}>Output</option><option value="in" ${n.source?.port==='in'?'selected':''}>Input · x</option></select></div>`;
 const incoming=model().edges.filter(e=>e.to===n.id),outgoing=model().edges.filter(e=>e.from===n.id);
 return `<div class="inspector-heading">Block inspector${button('clearselect','Deselect block','panel-right-close')}</div><div class="inspector-section"><div class="selected-block"><div class="selected-block-icon">${n.symbol}</div><div><b>${esc(n.name)}</b><p>${{function:'Nonlinear function',random:'Random source',parameter:'Constant parameter',tap:'Distribution observer',calculus:'Symbolic operator',delay:'Discrete dynamics'}[n.type]||n.category+' operator'}</p></div></div></div><div class="inspector-section"><h4>Parameters</h4>${params||'<p class="field-help">This block has no adjustable parameters.</p>'}</div><div class="inspector-section"><h4>Connections <span style="float:right;font-size:8px">${incoming.length+outgoing.length}</span></h4>${incoming.map(e=>`<div class="connection-row"><span><span class="port-indicator"></span>${esc(e.port)}</span><span class="connection-value">${esc(model().nodes.find(s=>s.id===e.from)?.name)} <button data-disconnect="${e.from}|${e.to}|${e.port}" title="Disconnect wire" style="color:#b2beb3">×</button></span></div>`).join('')}${outgoing.length?`<div class="connection-row"><span><span class="port-indicator"></span>out</span><span class="connection-value">${outgoing.length} connection${outgoing.length>1?'s':''}</span></div>`:''}${!incoming.length&&!outgoing.length?'<p class="field-help">Connect ports to route a signal.</p>':''}${n.type!=='tap'?`<button class="tap-btn" data-action="tapselection">${icon('plus')}Add output distribution tap</button>`:''}</div><div class="inspector-section"><h4>Output statistics <span class="dot" style="float:right"></span></h4><div class="stat-grid"><div><small>MEAN · μ</small><span>${fmt(s.mean)}</span></div><div><small>STD. DEV · σ</small><span>${fmt(s.sd)}</span></div><div><small>MINIMUM</small><span>${fmt(s.min)}</span></div><div><small>MAXIMUM</small><span>${fmt(s.max)}</span></div></div></div><div class="inspector-bottom"><div class="mode-badge">${icon('braces')}Symbolic expressions · seeded sampling</div><div style="display:flex;gap:8px;margin-top:15px">${button('copy','Copy block','copy','btn soft')}${button('delete','Delete block','trash-2','icon-btn')}</div></div>`;}
function simulationHTML(){const n=model().nodes.find(n=>n.op==='logistic')||model().nodes.find(n=>n.type==='function'),v=state.sim.values[n?.id]||[],s=stats(v),pts=v.slice(0,150);const points=pts.map((x,i)=>`${i/(pts.length-1)*700},${75-(x-s.min)/(s.max-s.min||1)*65}`).join(' ');return `${state.sim.errors.length?`<div class="error-list">${state.sim.errors.map(esc).join('<br>')}</div>`:''}<div class="simulation-summary"><div>Samples<b>${state.sim.count.toLocaleString()}</b></div><div>Iterations<b>${state.sim.iterations}</b></div><div>Output mean<b>${fmt(s.mean)}</b></div><div>Compute time<b>${Math.max(1,state.elapsed).toFixed(0)}<small style="font-size:10px"> ms</small></b></div><div style="margin-left:auto">${button('settings','Configure','sliders-horizontal','btn outline')}</div></div><svg class="analysis-graph" viewBox="0 0 700 90" preserveAspectRatio="none" role="img" aria-label="Output sample trace"><path d="M 0 25 H 700 M 0 50 H 700 M 0 75 H 700" stroke="#e5ece1" fill="none" stroke-dasharray="3 4"/><polyline points="${points}" fill="none" stroke="#79a785" stroke-width="1"/><text x="0" y="89" class="chart-axis">Sample 1</text><text x="640" y="89" class="chart-axis">Sample ${pts.length}</text></svg>`;}
function sourceHTML(){return `<div class="source-view"><div class="source-header">${icon('file-code-2')}<strong>model.sysml</strong><span class="note">Generated SysML 2.0 draft</span>${button('downloadsysml','Export','download','btn outline')}${button('source','Close source','x')}</div><p class="note">Editable graph is stored alongside this representation in model.json. Full SysML semantic validation is pending.</p><pre>${esc(toSysML(model()))}</pre></div>`;}
function splitHTML(){if(state.compare===state.active)state.compare=state.tabs.findIndex((_,i)=>i!==state.active);const t=state.tabs[state.compare];if(!t)return `<div class="split-container"><div class="split-title">Compare model${button('split','Merge view','x')}</div><div class="split-empty">Double-click any commit in version history to open another model, then split the view.</div></div>`;state.compareSim=simulate(t.model);return `<div class="split-container"><div class="split-title"><select class="branch-select" id="compare-tab" aria-label="Comparison model">${state.tabs.map((t,i)=>i!==state.active?`<option value="${i}" ${i===state.compare?'selected':''}>${esc(t.model.name)} · ${esc(t.model.branch)}</option>`:'').join('')}</select>${button('split','Merge view','x')}</div><div class="split-content" style="transform:scale(.52);width:820px">${graphHTML(t.model,true)}</div><div class="split-empty" style="padding-top:0;font-size:9px">Click a block above to copy it. Paste into the active design with Ctrl V.</div></div>`;}
function modal(title,content,actions='',large=false){$('#modal-root').innerHTML=`<div class="modal-overlay"><div class="modal ${large?'large':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><h2>${esc(title)}</h2>${content}<div class="modal-actions">${button('closemodal','Close',null,'btn outline')}${actions}</div></div></div>`;refreshIcons();setTimeout(()=>$('.modal input')?.focus(),30);}
function closeModal(){$('#modal-root').innerHTML='';}
function addBlock(op,x,y){edit(m=>{const n=makeNode(op,Math.max(10,x??180),Math.max(0,y??120));if(op==='tap'){n.name='Distribution tap';n.source=state.selected?{id:state.selected,port:'out'}:null;}m.nodes.push(n);state.selected=n.id;state.selection=new Set([n.id]);});toast('Block added · connect its ports to route a signal');}
function addTap(id,port='out'){const n=model().nodes.find(n=>n.id===id);if(!n||n.type==='tap')return;edit(m=>{const tap=makeNode('tap',n.x,Math.max(n.y+190,340));tap.name=port==='in'?'Input distribution':'Output distribution';tap.source={id,port};m.nodes.push(tap);state.selected=tap.id;state.selection=new Set([tap.id]);});state.tool='select';render();toast(`${port==='in'?'Input':'Output'} distribution tap attached`);}
async function refreshRepository(){[state.history,state.branches]=await Promise.all([repo.history(),repo.branches()]);state.heads=Object.fromEntries(await Promise.all(state.branches.map(async b=>[b,await repo.head(b)])));}
async function save(){
 if(state.busy)return;state.busy=true;const t=active(),snapshot=clone(t.model);render();
 try{let branch=snapshot.branch,head;try{head=await repo.head(branch);}catch{}if(head&&head!==t.base){branch='exploration-'+Date.now().toString(36);await repo.newBranch(branch,t.base);snapshot.branch=branch;t.model.branch=branch;}
 t.base=await repo.commitModel(snapshot,branch,snapshot.name);t.dirty=JSON.stringify(t.model)!==JSON.stringify(snapshot);await refreshRepository();persist();toast(`Committed ${t.base.slice(0,7)} on ${branch}`);
 }catch(e){toast('Could not commit: '+e.message);}finally{state.busy=false;render();}
}
async function openCommit(oid){try{const existing=state.tabs.findIndex(t=>t.base===oid&&!t.dirty);if(existing>=0){state.active=existing;}else{const m=await repo.readModel(oid);state.tabs.push({model:m,base:oid,dirty:false,undo:[],redo:[]});state.active=state.tabs.length-1;}state.selected='logistic';state.selection=new Set(['logistic']);state.pan={x:0,y:0};state.zoom=1;state.source=false;runSimulation();persist();render();toast('Commit opened in a model tab');}catch(e){toast('Could not open commit: '+e.message);}}
function undo(redo=false){const t=active(),from=redo?t.redo:t.undo,to=redo?t.undo:t.redo;if(!from.length)return;to.push(clone(t.model));t.model=from.pop();t.dirty=true;persist();runSimulation();render();}
function copyNodes(compareId){const m=compareId?state.tabs[state.compare].model:model(),ids=compareId?new Set([compareId]):state.selection;const nodes=m.nodes.filter(n=>ids.has(n.id));if(!nodes.length)return;state.clipboard={nodes:clone(nodes),edges:clone(m.edges.filter(e=>ids.has(e.from)&&ids.has(e.to)))};toast(`${nodes.length} block${nodes.length>1?'s':''} copied · paste into any model tab`);}
function paste(){if(!state.clipboard)return toast('Select a block and copy it first');edit(m=>{const map=new Map();const nodes=state.clipboard.nodes.map(n=>{const next=clone(n),id='n'+crypto.randomUUID().slice(0,8);map.set(n.id,id);return {...next,id,x:next.x+35,y:next.y+35};});for(const n of nodes)if(n.source)n.source=map.has(n.source.id)?{...n.source,id:map.get(n.source.id)}:m.nodes.some(s=>s.id===n.source.id)?n.source:null;m.nodes.push(...nodes);m.edges.push(...state.clipboard.edges.map(e=>({...e,from:map.get(e.from),to:map.get(e.to)})));state.selection=new Set(nodes.map(n=>n.id));state.selected=nodes[0]?.id;});toast('Pasted into '+model().name);}
function deleteSelected(){if(!state.selection.size)return;edit(m=>{m.nodes=m.nodes.filter(n=>!state.selection.has(n.id));m.edges=m.edges.filter(e=>!state.selection.has(e.from)&&!state.selection.has(e.to));for(const n of m.nodes)if(n.source&&state.selection.has(n.source.id))n.source=null;state.selection.clear();state.selected=null;});}
function download(data,name,type='text/plain'){const blob=data instanceof Blob?data:new Blob([data],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
const actions={
 workspace(){state.source=false;render();},library(){document.body.classList.remove('focus');$('#block-search')?.focus();toast('Drag a block onto the canvas, or double-click to add it.');},allblocks(){state.favorites=false;render();},favorites(){state.favorites=true;render();},
 rename(){modal('Name your model','<p>A model name becomes its commit message when you save.</p><div class="field"><label class="field-label" for="model-name">Model name</label><input class="field-input" id="model-name" maxlength="80" value="'+esc(model().name)+'"></div>',button('renamesubmit','Rename',null,'btn green'));},renamesubmit(){const name=$('#model-name').value.trim();if(!name)return;edit(m=>m.name=name);closeModal();},
 undo(){undo();},redo(){undo(true);},save,
 run(){runSimulation();render();toast(`Simulation complete · ${state.sim.count.toLocaleString()} samples · ${state.sim.iterations} iterations · ${state.elapsed.toFixed(0)} ms`);},
 source(){state.source=!state.source;render();},downloadsysml(){download(toSysML(model()),model().name.replace(/ /g,'_')+'.sysml');},
 git(){state.panel='history';state.panelClosed=false;render();},analytics(){state.panel='simulation';state.panelClosed=false;render();},togglepanel(){state.panelClosed=!state.panelClosed;render();},expandgit(){state.gitExpanded=!state.gitExpanded;state.panelClosed=false;render();},
 select(){state.tool='select';state.pending=null;render();},pan(){state.tool='pan';render();},tap(){state.tool=state.tool==='tap'?'select':'tap';state.pending=null;render();if(state.tool==='tap')toast('Click any input or output port to attach a live distribution tap.');},tapselection(){addTap(state.selected);},
 zoomin(){state.zoom=Math.min(1.8,state.zoom+.1);render();},zoomout(){state.zoom=Math.max(.35,state.zoom-.1);render();},fit(){state.zoom=1;state.pan={x:0,y:0};render();},split(){state.split=!state.split;state.source=false;render();},clearselect(){state.selection.clear();state.selected=null;render();},copy(){copyNodes();},delete(){deleteSelected();},
 new(){modal('Start a new exploration','<p>Every new design starts with a question.</p><div class="field"><label class="field-label" for="new-name">Model name</label><input class="field-input" id="new-name" placeholder="My next experiment" maxlength="80"></div><div class="field"><label class="field-label" for="new-template">Starting point</label><select class="field-input" id="new-template"><option value="logistic">Logistic map · connected system</option><option value="empty">Blank canvas</option><option value="normal">Normal → custom function</option></select></div>',button('newsubmit','Create model','plus','btn green'));},
 async newsubmit(){const name=$('#new-name').value.trim()||'Untitled exploration',template=$('#new-template').value,m=defaultModel();m.name=name;m.branch='model-'+Date.now().toString(36);if(template==='empty'){m.nodes=[];m.edges=[];}if(template==='normal'){m.nodes=m.nodes.filter(n=>['random','logistic','inputTap','outputTap'].includes(n.id));m.edges=m.edges.filter(e=>e.from==='random');m.nodes.find(n=>n.id==='random').op='normal';m.nodes.find(n=>n.id==='random').name='Normal';m.nodes.find(n=>n.id==='random').symbol='N';m.nodes.find(n=>n.id==='logistic').op='custom';m.nodes.find(n=>n.id==='logistic').name='Custom function';m.nodes.find(n=>n.id==='logistic').params.expression='x^2';m.iterations=1;}await repo.newBranch(m.branch,active().base);state.tabs.push({model:m,base:active().base,dirty:true,undo:[],redo:[]});state.active=state.tabs.length-1;state.selected=m.nodes[0]?.id;state.selection=new Set(state.selected?[state.selected]:[]);await refreshRepository();closeModal();runSimulation();persist();render();},
 newbranch(){modal('Branch your exploration','<p>Create a branch from the active model’s commit. Your current edits come with you.</p><div class="field"><label class="field-label" for="branch-name">Branch name</label><input class="field-input mono" id="branch-name" placeholder="experiment/new-idea" maxlength="70"></div>',button('branchsubmit','Create branch','git-branch','btn green'));},
 async branchsubmit(){try{const name=$('#branch-name').value.trim();await repo.newBranch(name,active().base);edit(m=>m.branch=name);await refreshRepository();closeModal();render();toast('Switched to branch '+name);}catch(e){toast(e.message);}},
 projects(){modal('Your open models',`<p>Each tab keeps its own working state and undo history.</p>${state.tabs.map((t,i)=>`<button class="export-option" data-open-tab="${i}"><span>${esc(t.model.name)}<small>${esc(t.model.branch)} · ${t.dirty?'uncommitted changes':t.base.slice(0,7)}</small></span>${icon('arrow-up-right')}</button>`).join('')}${JSON.parse(localStorage.getItem('chaos-lab-drafts-v1')||'[]').map((t,i)=>`<button class="export-option" data-restore-draft="${i}"><span>${esc(t.model.name)}<small>Closed draft · uncommitted changes</small></span>${icon('rotate-ccw')}</button>`).join('')}`,button('new','New model','plus','btn green'));},
 experiments(){modal('The experiment notebook','<p>Open a saved starting point, then make it your own.</p><div class="note-card">The logistic map demonstrates how a simple deterministic rule creates complex behavior. Try r = 3.2 for a stable cycle, 3.55 for period doubling, and 3.9 for chaos.</div>'+state.history.filter(c=>c.branch!=='main').map(c=>`<button class="export-option" data-open-commit="${c.oid}"><span>${esc(c.commit.message.split('\n')[0])}<small>${esc(c.branch)} · ${c.oid.slice(0,7)}</small></span>${icon('arrow-up-right')}</button>`).join(''),button('new','New experiment','plus','btn green'));},
 settings(){modal('Simulation settings','<p>Use the same seed to reproduce an exploration exactly.</p><div class="settings-grid"><div class="field"><label class="field-label">Samples</label><select class="field-input" id="settings-samples">'+[1000,5000,10000,25000,50000].map(n=>`<option value="${n}" ${model().samples===n?'selected':''}>${n.toLocaleString()}</option>`).join('')+'</select></div><div class="field"><label class="field-label">Iterations</label><input class="field-input mono" id="settings-iterations" type="number" min="1" max="100" value="'+model().iterations+'"></div></div><div class="field"><label class="field-label">Random seed</label><input class="field-input mono" id="settings-seed" type="number" value="'+model().seed+'"></div><div class="note-card">Sampling follows the connections in your graph. Feedback loops need a Unit delay block. Integration and differentiation operate on the block’s symbolic expression.</div>',button('settingssubmit','Apply & run','play','btn green'));},
 settingssubmit(){const samples=+$('#settings-samples').value,iterations=Math.min(100,Math.max(1,+$('#settings-iterations').value||1)),seed=+$('#settings-seed').value||42;edit(m=>{m.samples=samples;m.iterations=iterations;m.seed=seed;});closeModal();toast('Simulation settings updated');},
 export(){modal('Take your exploration with you','<p>Your repository is stored on this device. Export it to keep a portable copy or connect it to a Git remote using your own tools.</p><button class="export-option" data-action="exportgit"><span>Git repository<small>Complete .git history, branches, graph, and SysML model</small></span>'+icon('git-branch')+'</button><button class="export-option" data-action="downloadsysml"><span>SysML 2.0 draft<small>Generated textual model · .sysml</small></span>'+icon('file-code-2')+'</button><button class="export-option" data-action="exportjson"><span>Graph document<small>Current model, layout, connections, and parameters · .json</small></span>'+icon('braces')+'</button>');},
 async exportgit(){try{download(await repo.exportRepository(),'chaos-lab-repository.tar');toast('Repository exported with full Git history');}catch(e){toast(e.message);}},exportjson(){download(JSON.stringify(model(),null,2),'model.json','application/json');},
 help(){modal('A field guide to Chaos Lab','<p>Explore mathematical systems by connecting ideas.</p><div class="help-grid"><kbd>Drag / double-click</kbd><span>Add a block from the library</span><kbd>Click out → input</kbd><span>Connect blocks with a signal</span><kbd>T + click a port</kbd><span>Attach a distribution tap</span><kbd>Ctrl C / Ctrl V</kbd><span>Copy and paste across model tabs</span><kbd>Ctrl Z / Ctrl Shift Z</kbd><span>Undo and redo</span><kbd>Ctrl S</kbd><span>Create a Git commit</span><kbd>Double-click commit</kbd><span>Open a version in its own tab</span><kbd>H / V</kbd><span>Pan / select canvas tools</span><kbd>Delete / Backspace</kbd><span>Delete selected blocks</span><kbd>Ctrl A</kbd><span>Select all blocks</span><kbd>/</kbd><span>Search the block library</span></div><p style="font-size:10px;margin-top:24px">Local-first beta · symbolic math powered by Nerdamer · real Git objects powered by isomorphic-git. SysML export is an experimental representation; a full SysML parser and remote Git sync are future work. Beta sampling uses integer shape parameters.</p>');},closemodal:closeModal
};
function switchTab(index){if(index<0||index>=state.tabs.length)return;state.active=index;state.selected=state.tabs[index].model.nodes.find(n=>n.id==='logistic')?.id||state.tabs[index].model.nodes[0]?.id;state.selection=new Set(state.selected?[state.selected]:[]);state.pending=null;state.pan={x:0,y:0};state.zoom=1;state.source=false;runSimulation();persist();render();}
function onPort(el){const id=el.dataset.id,port=el.dataset.port;if(state.tool==='tap'&&port!=='tap')return addTap(id,port==='out'?'out':'in');if(port==='out'){state.pending={id};render();toast('Now click an input port to connect the blocks');return;}if(state.pending){const from=state.pending.id;if(from===id)return toast('Use a Unit delay to create a feedback loop');if(port==='tap'){edit(m=>m.nodes.find(n=>n.id===id).source={id:from,port:'out'});}else{edit(m=>{const src=m.nodes.find(n=>n.id===from),target=m.nodes.find(n=>n.id===id);const dest=src.type==='delay'&&target.type==='function'&&port==='x'?'feedback':port;m.edges=m.edges.filter(e=>!(e.to===id&&e.port===dest));m.edges.push({from,to:id,port:dest});});}state.pending=null;render();toast('Signal connected');}else toast('Click an output port first, then an input port');}
document.addEventListener('click',async e=>{
 const action=e.target.closest('[data-action]');if(action){const fn=actions[action.dataset.action];if(fn)try{await fn();}catch(err){toast(err.message);}return;}
 if(e.target.classList.contains('modal-overlay'))return closeModal();
 const close=e.target.closest('[data-close-tab]');if(close){const i=+close.dataset.closeTab;if(state.tabs[i].dirty){const archive=JSON.parse(localStorage.getItem('chaos-lab-drafts-v1')||'[]');archive.push(state.tabs[i]);localStorage.setItem('chaos-lab-drafts-v1',JSON.stringify(archive.slice(-20)));toast('Uncommitted model retained in drafts');}state.tabs.splice(i,1);state.active=Math.min(state.active,state.tabs.length-1);switchTab(state.active);return;}
 const tab=e.target.closest('[data-tab]');if(tab)return switchTab(+tab.dataset.tab);
 const draft=e.target.closest('[data-restore-draft]');if(draft){const drafts=JSON.parse(localStorage.getItem('chaos-lab-drafts-v1')||'[]'),t=drafts.splice(+draft.dataset.restoreDraft,1)[0];localStorage.setItem('chaos-lab-drafts-v1',JSON.stringify(drafts));state.tabs.push({...t,undo:[],redo:[]});closeModal();switchTab(state.tabs.length-1);return;}
 const open=e.target.closest('[data-open-tab]');if(open){closeModal();return switchTab(+open.dataset.openTab);}
 const commit=e.target.closest('[data-open-commit]');if(commit){closeModal();return openCommit(commit.dataset.openCommit);}
 const category=e.target.closest('[data-category]');if(category){const g=category.dataset.category;state.closed.has(g)?state.closed.delete(g):state.closed.add(g);$('#categories').innerHTML=libraryHTML();refreshIcons();return;}
 const port=e.target.closest('[data-port]');if(port)return onPort(port);
 const disconnect=e.target.closest('[data-disconnect]');if(disconnect){const [from,to,port]=disconnect.dataset.disconnect.split('|');edit(m=>m.edges=m.edges.filter(e=>!(e.from===from&&e.to===to&&e.port===port)));return;}
 const compare=e.target.closest('[data-compare-node]');if(compare)return copyNodes(compare.dataset.node);
 const node=e.target.closest('[data-node]');if(node){if(state.justDragged){state.justDragged=false;return;}const id=node.dataset.node;if(e.shiftKey||e.ctrlKey||e.metaKey){state.selection.has(id)?state.selection.delete(id):state.selection.add(id);}else state.selection=new Set([id]);state.selected=id;$('#plane').innerHTML=graphHTML(model());$('#inspector').innerHTML=inspectorHTML();refreshIcons();return;}
 if(e.target.id==='canvas'||e.target.id==='plane'){state.pending=null;if(state.tool==='select'){state.selection.clear();state.selected=null;render();}}
});
document.addEventListener('dblclick',e=>{const block=e.target.closest('[data-block]');if(block)return addBlock(block.dataset.block,100+Math.random()*300,80+Math.random()*150);const commit=e.target.closest('[data-commit]');if(commit)return openCommit(commit.dataset.commit);});
document.addEventListener('keydown',e=>{
 const typing=/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName),mod=e.ctrlKey||e.metaKey;
 if(e.key==='Escape'){state.pending=null;state.tool='select';if($('#modal-root').innerHTML)closeModal();else{state.source=false;render();}return;}
 if(typing){if(e.key==='Enter'&&$('.modal')){const submit=$('.modal-actions .green');submit?.click();}return;}
 if(e.key==='Enter'){const c=e.target.closest('[data-commit]'),b=e.target.closest('[data-block]'),t=e.target.closest('[data-tab]');if(c)openCommit(c.dataset.commit);if(b)addBlock(b.dataset.block);if(t)switchTab(+t.dataset.tab);return;}
 if(mod&&e.key.toLowerCase()==='s'){e.preventDefault();save();return;}if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);return;}if(mod&&e.key.toLowerCase()==='y'){e.preventDefault();undo(true);return;}if(mod&&e.key.toLowerCase()==='c'){e.preventDefault();copyNodes();return;}if(mod&&e.key.toLowerCase()==='v'){e.preventDefault();paste();return;}if(mod&&e.key.toLowerCase()==='a'){e.preventDefault();state.selection=new Set(model().nodes.map(n=>n.id));render();return;}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelected();return;}if(e.key==='/'){e.preventDefault();$('#block-search')?.focus();return;}if(e.key.toLowerCase()==='t')actions.tap();if(e.key.toLowerCase()==='h')actions.pan();if(e.key.toLowerCase()==='v')actions.select();
});
function updateParam(key,value,renderNow=true){const n=model().nodes.find(n=>n.id===state.selected);if(!n)return;const current=n.params;if(key!=='expression'&&!Number.isFinite(+value))return toast('Enter a finite number');if(key==='sigma'&&+value<=0||key==='lambda'&&+value<=0||['a','b'].includes(key)&&n.op==='beta'&&(+value<1||!Number.isInteger(+value)))return toast('Enter a positive value. Beta shape parameters must be whole numbers.');if(key==='p'&&(value<0||value>1))return toast('Probability must be between 0 and 1');if(key==='min'&&+value>=current.max||key==='max'&&+value<=current.min)return toast('Maximum must be greater than minimum');edit(m=>{if(key==='r'){const e=m.edges.find(e=>e.to===n.id&&e.port==='r'),param=m.nodes.find(n=>n.id===e?.from);if(param?.type==='parameter')param.params.value=+value;else m.nodes.find(s=>s.id===n.id).params.r=+value;}else m.nodes.find(s=>s.id===n.id).params[key]=key==='expression'?value:+value;},renderNow);}
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.param)return updateParam(el.dataset.param,el.value);if(el.id==='branch-filter'){state.filter=el.value;render();}if(el.id==='compare-tab'){state.compare=+el.value;render();}if(el.id==='tap-source'||el.id==='tap-port'){const source=$('#tap-source').value,port=$('#tap-port').value;edit(m=>m.nodes.find(n=>n.id===state.selected).source=source?{id:source,port}:null);}});
let rangeStart;
document.addEventListener('pointerdown',e=>{if(e.target.dataset.range)rangeStart=clone(model());});
document.addEventListener('input',e=>{if(e.target.dataset.range){const n=model().nodes.find(n=>n.id===state.selected);const edge=model().edges.find(e=>e.to===n.id&&e.port==='r'),param=model().nodes.find(n=>n.id===edge?.from);if(param?.type==='parameter')param.params.value=+e.target.value;else n.params.r=+e.target.value;active().dirty=true;clearTimeout(runTimer);runTimer=setTimeout(()=>{runSimulation();$('#plane').innerHTML=graphHTML(model());const number=$('[data-param="r"]');if(number)number.value=e.target.value;refreshIcons();persist();},45);}});
document.addEventListener('pointerup',e=>{if(rangeStart){active().undo.push(rangeStart);active().redo=[];rangeStart=null;persist();clearTimeout(runTimer);runSimulation();render();}});
document.addEventListener('dragstart',e=>{const block=e.target.closest('[data-block]');if(block){e.dataTransfer.setData('application/chaos-block',block.dataset.block);e.dataTransfer.effectAllowed='copy';}});
document.addEventListener('dragover',e=>{if(e.target.closest('#canvas')&&!e.target.closest('.split-container')){e.preventDefault();e.dataTransfer.dropEffect='copy';}});
document.addEventListener('drop',e=>{if(!e.target.closest('#canvas'))return;e.preventDefault();const op=e.dataTransfer.getData('application/chaos-block');if(!op)return;const rect=$('#plane').getBoundingClientRect(),scale=rect.width/820;addBlock(op,(e.clientX-rect.left)/scale-70,(e.clientY-rect.top)/scale-20);});
document.addEventListener('pointerdown',e=>{
 if(e.button!==0||e.target.closest('button,input,select,.source-view,.split-container'))return;
 const node=e.target.closest('#plane [data-node]'),canvas=e.target.closest('#canvas');if(!canvas)return;
 const panning=state.tool==='pan'||e.altKey;if(!node&&!panning)return;
 const start={x:e.clientX,y:e.clientY},before=clone(model()),scale=$('#plane').getBoundingClientRect().width/820,n=node?model().nodes.find(n=>n.id===node.dataset.node):null,positions=new Map(model().nodes.filter(s=>state.selection.has(n?.id)?state.selection.has(s.id):s.id===n?.id).map(s=>[s.id,{x:s.x,y:s.y}])),pan={...state.pan};let moved=false;
 function move(ev){const dx=(ev.clientX-start.x)/scale,dy=(ev.clientY-start.y)/scale;if(Math.abs(dx)+Math.abs(dy)<3)return;moved=true;if(panning){state.pan={x:pan.x+ev.clientX-start.x,y:pan.y+ev.clientY-start.y};$('#plane').style.transform=`translate(${state.pan.x}px,${state.pan.y}px) scale(${canvasScale()*state.zoom})`;}else{for(const [id,pos]of positions){const target=model().nodes.find(s=>s.id===id);target.x=Math.max(0,pos.x+dx);target.y=Math.max(0,pos.y+dy);}$('#plane').innerHTML=graphHTML(model());refreshIcons();}}
 function up(){document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);if(moved&&!panning){active().undo.push(before);active().redo=[];active().dirty=true;persist();state.justDragged=true;setTimeout(()=>state.justDragged=false,100);render();}}
 document.addEventListener('pointermove',move);document.addEventListener('pointerup',up);
});
document.addEventListener('wheel',e=>{if(!e.target.closest('#canvas')||e.target.closest('.source-view,.split-container'))return;e.preventDefault();if(e.ctrlKey||e.metaKey){state.zoom=Math.max(.35,Math.min(1.8,state.zoom-e.deltaY*.002));}else{state.pan.x-=e.deltaX;state.pan.y-=e.deltaY;}$('#plane').style.transform=`translate(${state.pan.x}px,${state.pan.y}px) scale(${canvasScale()*state.zoom})`;$('.zoom-label').textContent=Math.round(state.zoom*100)+'%';},{passive:false});
window.addEventListener('resize',()=>{if(state.tabs.length)render();});
async function boot(){try{const main=await repo.initRepository();await refreshRepository();let stored;try{stored=JSON.parse(localStorage.getItem('chaos-lab-tabs-v1'));}catch{}if(stored?.tabs?.length){state.tabs=stored.tabs.map(t=>({...t,undo:[],redo:[]}));state.active=Math.min(stored.active||0,state.tabs.length-1);}else{const m=await repo.readModel(main),branch=await repo.head('edge-of-chaos'),experiment=await repo.readModel(branch);state.tabs=[{model:m,base:main,dirty:false,undo:[],redo:[]},{model:experiment,base:branch,dirty:false,undo:[],redo:[]}];}runSimulation();render();window.chaosLab={getState:()=>state,repo,simulate};}catch(e){$('#app').innerHTML=`<div class="boot"><div class="boot-logo">∿</div><strong>Could not open the local repository.</strong><span>${esc(e.message)}</span><p>Enable browser storage and reload to start your workspace.</p><button class="btn outline" onclick="location.reload()">Try again</button></div>`;console.error(e);}}
boot();
